function removeKdigits(num, k) {
  const stack = [];
  let budget = k;
  for (const digit of num) {
    while (budget > 0 && stack.length > 0 && stack[stack.length - 1] > digit) {
      stack.pop();
      budget--;
    }
    stack.push(digit);
  }
  const kept = stack.slice(0, stack.length - budget);
  const trimmed = kept.join("").replace(/^0+/, "");
  return trimmed === "" ? "0" : trimmed;
}

